chrome.runtime.onInstalled.addListener(()=>{console.log("PostureAI installed"),chrome.storage.local.get("settings",e=>{e.settings||chrome.storage.local.set({settings:{goodThreshold:165,warnThreshold:150,alertEnabled:!0,alertDelayMinutes:3,soundEnabled:!0,soundVolume:70,autoStartOnLaunch:!1,pauseOnIdle:!0,idleTimeoutMinutes:10,showLiveAngle:!0,showSkeleton:!0,showConfidenceScore:!1,notifyBadPosture:!0,notifyStreakMilestone:!0,notifySessionSummary:!0,mirrorCamera:!0}})})});chrome.notifications.onClicked.addListener(e=>{chrome.action.openPopup()});chrome.runtime.onMessage.addListener((e,s,o)=>(e.type==="BAD_POSTURE_ALERT"&&chrome.storage.local.get("settings",t=>{(t.settings||{}).notifyBadPosture&&chrome.notifications.create({type:"basic",iconUrl:"icons/icon48.png",title:"PostureAI — Tech Neck Alert",message:`Your posture angle dropped to ${e.angle}°. Time for a 30-second reset.`,priority:1})}),e.type==="STREAK_MILESTONE"&&chrome.storage.local.get("settings",t=>{(t.settings||{}).notifyStreakMilestone&&chrome.notifications.create({type:"basic",iconUrl:"icons/icon48.png",title:"PostureAI — Streak Milestone! 🔥",message:e.text,priority:1})}),o({ok:!0}),!0));
